/* ===== INTRO ===== */
const iv=$('#iv'),intro=$('#intro');
let ended=false;
function endIntro(){if(ended)return;ended=true;iv.pause();intro.classList.add('out');document.body.classList.remove('lock');setTimeout(()=>intro.remove(),800)}
iv.src=innerHeight>innerWidth?A.videoP:A.videoL;
iv.addEventListener('ended',endIntro);iv.addEventListener('error',endIntro);
$('#skip').onclick=endIntro;
iv.muted=false;iv.volume=1;
let failsafe=setTimeout(endIntro,16000);
iv.play().catch(()=>{
 /* Browser blocks autoplay WITH sound until the visitor touches the page (a browser rule websites cannot override).
    No button or label is shown: the intro just plays; if the visitor touches/clicks/presses a key meanwhile, it restarts with sound. */
 iv.muted=true;iv.play().catch(()=>endIntro());
 const ev=['pointerdown','touchstart','keydown','click','wheel'];
 const on=e=>{ev.forEach(t=>removeEventListener(t,on,true));if(ended||(e.target&&e.target.id==='skip'))return;
  clearTimeout(failsafe);iv.muted=false;iv.currentTime=0;iv.play().catch(()=>{iv.muted=true;iv.play()});failsafe=setTimeout(endIntro,9000)};
 ev.forEach(t=>addEventListener(t,on,{capture:true,passive:true}));
});
