const zxl=document.createElement('dialog');zxl.id='zxl';zxl.innerHTML='<button class="zxc" aria-label="Close">×</button><button class="zxn zxp" aria-label="Previous photo">‹</button><button class="zxn zxx" aria-label="Next photo">›</button><img alt=""><p></p>';document.body.append(zxl);
let zl=[],zk=0;
function zshow(){const g=zl[zk];zxl.querySelector('img').src=g.src;zxl.querySelector('img').alt=g.title;zxl.querySelector('p').textContent=g.title+(zl.length>1?' ('+(zk+1)+'/'+zl.length+')':'');$$('.zxn',zxl).forEach(b=>b.hidden=zl.length<2)}
function zopen(list,i=0){zl=list;zk=i;zshow();zxl.showModal()}
const zstep=d=>{zk=(zk+d+zl.length)%zl.length;zshow()};
zxl.querySelector('.zxc').onclick=()=>zxl.close();zxl.querySelector('.zxp').onclick=()=>zstep(-1);zxl.querySelector('.zxx').onclick=()=>zstep(1);
zxl.addEventListener('click',e=>{if(e.target===zxl)zxl.close()});
zxl.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')zstep(-1);if(e.key==='ArrowRight')zstep(1)});
$$('#zx .zsv[data-s]').forEach(b=>b.onclick=()=>zopen(ZP[+b.dataset.s]));
$$('#zx .zra').forEach(b=>b.onclick=()=>zopen(RA,+b.dataset.r));
$$('#zx .zgi[data-i]').forEach(b=>b.onclick=()=>zopen(ZX.gallery,+b.dataset.i));
const zio=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');zio.unobserve(e.target)}}),{root:zx,threshold:.1});
$$('#zx .zr').forEach(x=>zio.observe(x));
